514	/**
515	 * Spawns `node scripts/build-personas.js` in the workspace root, capturing
516	 * combined stdout+stderr output.
517	 *
518	 * Concurrency guard: returns 409 Conflict when a build is already in progress.
519	 * The `buildInProgress` flag is cleared in a `finally` block to handle
520	 * unexpected process errors.
521	 *
522	 * @param workspaceRoot - Absolute path to the workspace root (contains `scripts/`).
523	 */
524	export async function handleRebuildPersonas(workspaceRoot: string): Promise<{
525	  success: true;
526	  output: string;
527	} | {
528	  success: false;
529	  output: string;
530	  exitCode: number;
531	}> {
532	  if (buildInProgress) {
533	    throw new ApiError(
534	      'CONFLICT',
535	      'A persona build is already in progress. Please wait for it to complete.'
536	    );
537	  }
538	
539	  buildInProgress = true;
540	
541	  try {
542	    const output = await new Promise<{ output: string; exitCode: number }>(
543	      (resolve) => {
544	        const scriptPath = join(workspaceRoot, 'scripts', 'build-personas.js');
545	        const child = spawn('node', [scriptPath], {
546	          cwd: workspaceRoot,
547	          env: process.env,
548	        });
549	
550	        const chunks: string[] = [];
551	
552	        child.stdout.on('data', (chunk: Buffer) => {
553	          chunks.push(chunk.toString());
554	        });
555	
556	        child.stderr.on('data', (chunk: Buffer) => {
557	          chunks.push(chunk.toString());
558	        });
559	
560	        child.on('close', (code: number | null) => {
561	          resolve({ output: chunks.join(''), exitCode: code ?? 1 });
562	        });
563	
564	        child.on('error', (err: Error) => {
565	          resolve({
566	            output: `Process error: ${err.message}`,
567	            exitCode: 1,
568	          });
569	        });
570	      }
571	    );
572	
573	    if (output.exitCode === 0) {
574	      return { success: true, output: output.output };
575	    } else {
576	      return { success: false, output: output.output, exitCode: output.exitCode };
577	    }
578	  } finally {
579	    buildInProgress = false;
580	  }
581	}
